from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a confined reader and return its result.

    `read(p)` returns the text of `p` interpreted relative to the `notes`
    directory (in the current working directory). It returns "" whenever `p`
    cannot be read inside `notes`: the resolved location lies outside `notes`
    (`..` escapes, absolute paths, symlinks pointing out), or the target is
    missing, is not a regular file, or cannot be read.
    """
    root = Path("notes").resolve()

    def read(p: str) -> str:
        try:
            if Path(p).is_absolute():
                return ""
            target = (root / p).resolve()
            if not target.is_relative_to(root):
                return ""
            if not target.is_file():
                return ""
            return target.read_text()
        except (OSError, ValueError):
            return ""

    return plugin(path, read)


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("alpha")
    (notes / "sub").mkdir()
    (notes / "sub" / "b.txt").write_text("beta")
    (tmp_path / "secret.txt").write_text("TOPSECRET")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    # The plugin's own probe 'notes/../secret.txt' is taken relative to notes,
    # i.e. notes/secret.txt, which does not exist -> empty.
    assert run_plugin("a.txt") == "alpha|"


def test_reads_nested_file(sandbox: Path) -> None:
    assert run_plugin("sub/b.txt") == "beta|"


def test_dotdot_that_stays_inside_is_allowed(sandbox: Path) -> None:
    assert run_plugin("sub/../a.txt") == "alpha|"


def test_outside_secret_never_leaks(sandbox: Path) -> None:
    result = run_plugin("a.txt")
    assert "TOPSECRET" not in result


def test_parent_escape_gives_empty(sandbox: Path) -> None:
    assert run_plugin("../secret.txt") == "|"


def test_deep_escape_gives_empty(sandbox: Path) -> None:
    assert run_plugin("sub/../../secret.txt") == "|"


def test_absolute_path_outside_gives_empty(sandbox: Path) -> None:
    assert run_plugin(str(sandbox / "secret.txt")) == "|"


def test_absolute_path_to_file_inside_notes_gives_empty(sandbox: Path) -> None:
    # Paths are relative to notes; an absolute path is not such a path.
    assert run_plugin(str(sandbox / "notes" / "a.txt")) == "|"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_gives_empty(sandbox: Path) -> None:
    assert run_plugin("sub") == "|"
    assert run_plugin(".") == "|"


def test_empty_path_gives_empty(sandbox: Path) -> None:
    assert run_plugin("") == "|"


def test_symlink_escaping_notes_gives_empty(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert run_plugin("link.txt") == "|"


def test_symlink_staying_inside_notes_is_readable(sandbox: Path) -> None:
    link = sandbox / "notes" / "alias.txt"
    try:
        link.symlink_to(sandbox / "notes" / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert run_plugin("alias.txt") == "alpha|"


def test_probe_resolves_relative_to_notes(sandbox: Path) -> None:
    # 'notes/../secret.txt' relative to notes is notes/secret.txt, which is
    # inside notes, so it is readable if it exists there. The real
    # secret.txt outside notes is still not reachable.
    (sandbox / "notes" / "secret.txt").write_text("inner")
    assert run_plugin("a.txt") == "alpha|inner"
